+static bool ValueFitsTargetType(ir::TSAsExpression *expr, checker::Type *targetType, ETSChecker *checker)
+{
+    if (!expr->Expr()->IsNumberLiteral() || !IsNumericConstantCastTarget(checker, targetType)) {
+        return true;
+    }
+
+    lexer::Number number = NormalizeNumberLiteralForTarget(expr, checker, targetType);
+
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalByteBuiltinType())) {
+        return number.CanGetValue<int8_t>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalShortBuiltinType())) {
+        return number.CanGetValue<int16_t>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalIntBuiltinType())) {
+        return number.CanGetValue<int32_t>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalLongBuiltinType())) {
+        return number.CanGetValue<int64_t>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalFloatBuiltinType())) {
+        return number.CanGetValue<float>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalDoubleBuiltinType())) {
+        return number.CanGetValue<double>();
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalCharBuiltinType())) {
+        if (number.IsReal()) {
+            return false;
+        }
+
+        auto const value = number.GetValueAndCastTo<int64_t>();
+        return value >= std::numeric_limits<uint16_t>::min() && value <= std::numeric_limits<uint16_t>::max();
     }

     return true;
 }

+static Type *CreateConstantNumericCastType(ir::TSAsExpression *expr, Type *targetType, ETSChecker *checker)
+{
+    lexer::Number number = NormalizeNumberLiteralForTarget(expr, checker, targetType);
+
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalByteBuiltinType())) {
+        return checker->CreateByteType(number.GetValueAndCastTo<int8_t>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalShortBuiltinType())) {
+        return checker->CreateShortType(number.GetValueAndCastTo<int16_t>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalIntBuiltinType())) {
+        return checker->CreateIntType(number.GetValueAndCastTo<int32_t>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalLongBuiltinType())) {
+        return checker->CreateLongType(number.GetValueAndCastTo<int64_t>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalFloatBuiltinType())) {
+        return checker->CreateFloatType(number.GetValueAndCastTo<float>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalDoubleBuiltinType())) {
+        return checker->CreateDoubleType(number.GetValueAndCastTo<double>());
+    }
+    if (checker->Relation()->IsIdenticalTo(targetType, checker->GlobalCharBuiltinType())) {
+        return checker->CreateCharType(static_cast<char16_t>(number.GetValueAndCastTo<uint16_t>()));
+    }
+
+    return nullptr;
+}
