+bool IsPredefinedIntegerTypeReference(const ir::TypeNode *typeAnnotation)
+{
+    if (typeAnnotation == nullptr || !typeAnnotation->IsETSTypeReference()) {
+        return false;
+    }
+
+    const auto &name = typeAnnotation->AsETSTypeReference()->BaseName()->Name();
+    return name == compiler::Signatures::BUILTIN_BYTE_CLASS || name == compiler::Signatures::BUILTIN_SHORT_CLASS ||
+           name == compiler::Signatures::BUILTIN_INT_CLASS || name == compiler::Signatures::BUILTIN_LONG_CLASS;
+}
+
+bool HasUnsupportedTupleIndexAnnotation(const ir::TypeNode *typeAnnotation)
+{
+    return typeAnnotation != nullptr && !typeAnnotation->IsETSPrimitiveType() &&
+           !IsPredefinedIntegerTypeReference(typeAnnotation);
+}
+
+const ir::TypeNode *FindGlobalClassPropertyTypeAnnotation(const ir::Identifier *ident)
+{
+    for (auto *node = ident->Parent(); node != nullptr; node = node->Parent()) {
+        if (!node->IsClassDefinition()) {
+            continue;
+        }
+
+        auto *const classDef = node->AsClassDefinition();
+        if (!classDef->IsGlobal()) {
+            return nullptr;
+        }
+
+        for (auto *const member : classDef->Body()) {
+            if (!member->IsClassProperty()) {
+                continue;
+            }
+
+            auto *const prop = member->AsClassProperty();
+            if (prop->Key() != nullptr && prop->Key()->IsIdentifier() &&
+                prop->Key()->AsIdentifier()->Name() == ident->Name()) {
+                return prop->TypeAnnotation();
+            }
+        }
+
+        return nullptr;
+    }
+
+    return nullptr;
+}
+
+bool HasUnsupportedTupleIndexIdentifierAnnotation(const ir::Expression *expr)
+{
+    if (!expr->IsIdentifier()) {
+        return false;
+    }
+
+    auto *const ident = expr->AsIdentifier();
+    auto *const variable = expr->AsIdentifier()->Variable();
+    if (variable == nullptr || variable->Declaration() == nullptr || variable->Declaration()->Node() == nullptr) {
+        return HasUnsupportedTupleIndexAnnotation(FindGlobalClassPropertyTypeAnnotation(ident));
+    }
+
+    auto *const node = variable->Declaration()->Node();
+    if (node->IsClassProperty()) {
+        return HasUnsupportedTupleIndexAnnotation(node->AsClassProperty()->TypeAnnotation());
+    }
+
+    if (!node->IsVariableDeclarator()) {
+        return HasUnsupportedTupleIndexAnnotation(FindGlobalClassPropertyTypeAnnotation(ident));
+    }
+
+    auto *const declId = node->AsVariableDeclarator()->Id();
+    if (declId == nullptr || !declId->IsAnnotatedExpression()) {
+        return false;
+    }
+
+    auto *const typeAnnotation = declId->AsAnnotatedExpression()->TypeAnnotation();
+    return HasUnsupportedTupleIndexAnnotation(typeAnnotation);
+}
+
+bool IsTupleIndexIntegralType(ETSChecker *checker, const ir::Expression *expr, Type *type)
+{
+    if (type == nullptr) {
+        return false;
+    }
+
+    if (HasUnsupportedTupleIndexIdentifierAnnotation(expr)) {
+        return false;
+    }
+
+    if (type->HasTypeFlag(TypeFlag::ETS_ARRAY_INDEX | TypeFlag::LONG)) {
+        return true;
+    }
+
+    if (auto *unboxedType = checker->MaybeUnboxInRelation(type); unboxedType != nullptr) {
+        return unboxedType->HasTypeFlag(TypeFlag::ETS_ARRAY_INDEX | TypeFlag::LONG);
+    }
+
+    return false;
+}
