+static const ir::TSEnumDeclaration *FindEnumDeclarationForInitializer(const ir::TSAsExpression *expr)
+{
+    auto *child = static_cast<const ir::AstNode *>(expr);
+    for (auto *parent = expr->Parent(); parent != nullptr; child = parent, parent = parent->Parent()) {
+        if (parent->IsTSEnumMember()) {
+            if (parent->AsTSEnumMember()->Init() != child) {
+                return nullptr;
+            }
+
+            auto *enumDecl = parent->Parent();
+            return (enumDecl != nullptr) && enumDecl->IsTSEnumDeclaration() ? enumDecl->AsTSEnumDeclaration() : nullptr;
+        }
+    }
+
+    return nullptr;
+}
+
+static bool IsFoldableEnumInitializerCast(const ir::TSAsExpression *expr)
+{
