               expressionType->AsETSObjectType()->HasObjectFlag(ETSObjectFlags::NUMERIC_ENUM_OBJECT)) {
        expr->AddAstNodeFlags(ir::AstNodeFlags::GENERATE_VALUE_OF);
    }
    if (!expressionType->IsConstantType() || !expr->IsNumberLiteral()) {
